2210	// ---- THE SCORE ------------------------------------------------------------
2211	/**
2212	 * Everything the final outcome is computed from. Deliberately a plain data
2213	 * structure with no `Client`, no SSH and no clock: the scoring rule is the one
2214	 * piece of this engine that decides what the customer is TOLD, and it was wrong
2215	 * in production for months (`Sites actually serving: 4/4` with six domains
2216	 * dark). A rule that cannot be run in a test is a rule nobody can check, so it
2217	 * is extracted here and exercised by `test/migration-gate.test.ts` instead of
2218	 * only ever being exercised by a real customer's cutover.
2219	 */
2220	export type MigrationScoreInput = {
2221	  /**
2222	   * Every hostname the SOURCE server answered on, from its own live vhost
2223	   * config. THE DENOMINATOR. Empty means the source inventory could not be read
2224	   * — we then have no honest denominator and say so rather than scoring
2225	   * ourselves against our own homework.
2226	   */
2227	  sourceDomains: string[];
2228	  /** The names actually probed (the probe budget caps this below sourceDomains). */
2229	  probeNames: string[];
2230	  /** Per-domain probe verdicts. Only `serving: true` counts towards the score. */
2231	  siteProbes: { domain: string; serving: boolean }[];
2232	  /** Units the exec pre-flight / health gate refused to certify as running. */
2233	  unitBlockers: { domain: string }[];
2234	};
2235	
2236	export type MigrationScore = {
2237	  /** The set the score was measured against (sourceDomains, or probeNames as a named fallback). */
2238	  scoredAgainst: string[];
2239	  /** How many of `scoredAgainst` are serving. */
2240	  servingCount: number;
2241	  /** Everything in `scoredAgainst` that is not serving — failed AND unchecked. */
2242	  unservedDomains: string[];
2243	  /** Unserved names we DID probe: these are known-broken. */
2244	  failedProbe: string[];
2245	  /** Unserved names we never probed: "we did not check" is not "it works". */
2246	  uncheckedDomains: string[];
2247	  outcome: MigrationOutcome;
2248	  outcomeReasons: string[];
2249	};
2250	
2251	/**
2252	 * Decide the terminal outcome of a run. Extracted from `runRealMigration` so it
2253	 * is testable in isolation — see MigrationScoreInput.
2254	 *
2255	 * The invariant that matters, and the one the 2026-07-25 run violated: this
2256	 * function can return COMPLETED **only** when every hostname the old server
2257	 * answered on serves here and every migrated unit is healthy. A denominator we
2258	 * get to pick is not a measurement, so `sourceDomains` (read off the source)
2259	 * wins over `probeNames` (chosen by us), and falling back to `probeNames` is
2260	 * itself an outcome reason.
2261	 */
2262	export function judgeMigrationOutcome(input: MigrationScoreInput): MigrationScore {
2263	  const servingSet = new Set(input.siteProbes.filter((p) => p.serving).map((p) => p.domain));
2264	  const probedSet = new Set(input.probeNames);
2265	  const scoredAgainst = input.sourceDomains.length ? input.sourceDomains : input.probeNames;
2266	
2267	  // Everything the old server served that this one does not. A name we did not
2268	  // get to probe counts here too — "we did not check" is not "it works" — but it
2269	  // is worded separately so the customer is never told a site is broken when
2270	  // what we actually mean is that we ran out of probe budget.
2271	  const unservedDomains = scoredAgainst.filter((d) => !servingSet.has(d));
2272	  const failedProbe = unservedDomains.filter((d) => probedSet.has(d));
2273	  const uncheckedDomains = unservedDomains.filter((d) => !probedSet.has(d));
2274	
2275	  // Anything on this list means the customer's move is NOT finished, however
2276	  // many individual steps succeeded.
2277	  const outcomeReasons: string[] = [];
2278	  if (failedProbe.length) {
2279	    outcomeReasons.push(
2280	      `${failedProbe.length} of the ${scoredAgainst.length} domain(s) the old server answered on ${failedProbe.length === 1 ? "does" : "do"} not serve here: ${failedProbe.slice(0, 8).join(", ")}${failedProbe.length > 8 ? " …" : ""}`
2281	    );
2282	  }
2283	  if (uncheckedDomains.length) {
2284	    outcomeReasons.push(
2285	      `${uncheckedDomains.length} domain(s) the old server answered on were not checked at all: ${uncheckedDomains.slice(0, 6).join(", ")}${uncheckedDomains.length > 6 ? " …" : ""}`
2286	    );
2287	  }
2288	  if (input.unitBlockers.length) {
2289	    outcomeReasons.push(
2290	      `${input.unitBlockers.length} migrated service(s) are not running: ${input.unitBlockers.slice(0, 5).map((b) => b.domain).join(", ")}${input.unitBlockers.length > 5 ? " …" : ""}`
2291	    );
2292	  }
2293	  if (!input.sourceDomains.length && input.probeNames.length) {
2294	    outcomeReasons.push(
2295	      "the old server's live configuration could not be read, so this score is measured against the sites we published rather than against everything the old server served — check the rest by hand"
2296	    );
2297	  }
2298	
2299	  return {
2300	    scoredAgainst,
2301	    servingCount: scoredAgainst.filter((d) => servingSet.has(d)).length,
2302	    unservedDomains,
2303	    failedProbe,
2304	    uncheckedDomains,
2305	    outcome: outcomeReasons.length ? "COMPLETED_WITH_ISSUES" : "COMPLETED",
2306	    outcomeReasons,
2307	  };
2308	}
