2338	/**
2339	 * Fold systemd's line continuations. A unit may legally spread one ExecStart over

2339	 * Fold systemd's line continuations. A unit may legally spread one ExecStart over
2340	 * several lines with a trailing backslash, and reading it line-at-a-time would
2341	 * see a directive whose command is empty and skip the check entirely.
2342	 */
2343	export function unfoldUnitLines(text: string): string[] {
2344	  const out: string[] = [];
2345	  let acc = "";
2346	  for (const raw of String(text ?? "").split("\n")) {
2347	    const line = raw.replace(/\r$/, "");
2348	    if (/\\\s*$/.test(line)) {
2349	      acc += line.replace(/\\\s*$/, " ");
2350	      continue;
2351	    }
2352	    out.push((acc + line).trim());
2353	    acc = "";
2354	  }
2355	  if (acc.trim()) out.push(acc.trim());
2356	  return out;
2357	}
