2359	/**
2360	 * Every ABSOLUTE executable path a unit's Exec* directives will try to run.
2361	 *
2362	 * Defensive by design, because a unit file is untrusted input from another
2363	 * machine:
2364	 *   - `ExecStart=-/path`  the `-` (ignore failure), `@` (argv[0] override),
2365	 *     `+` (full privileges), `!` / `!!` (no-setuid variants) prefixes may appear
2366	 *     in any order and combination and are stripped before the path is read;
2367	 *   - quoted paths (`ExecStart="/opt/my app/bin/run" --flag`) are unquoted;
2368	 *   - an EMPTY assignment (`ExecStart=`) is systemd's list-reset and is skipped;
2369	 *   - a bare command (`ExecStart=node server.js`) is resolved from PATH by
2370	 *     systemd itself, so it is deliberately IGNORED — we cannot check it and
2371	 *     guessing would be worse than silence;
2372	 *   - a path carrying a `%` specifier (`/usr/bin/%i`) can only be resolved by
2373	 *     systemd, so it is skipped rather than mis-reported. It also would not pass
2374	 *     PATH_RE, which is what keeps every value here shell-inert.
2375	 */
2376	export function parseUnitExecPaths(text: string): UnitExecRef[] {
2377	  const out: UnitExecRef[] = [];
2378	  const seen = new Set<string>();
2379	  for (const line of unfoldUnitLines(text)) {
2380	    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
2381	    if (!m) continue;
2382	    let rhs = m[2].trim();
2383	    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
2384	    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
2385	    if (!rhs) continue;
2386	    let exe: string;
2387	    const q = rhs[0];
2388	    if (q === '"' || q === "'") {
2389	      const end = rhs.indexOf(q, 1);
2390	      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
2391	    } else {
2392	      exe = rhs.split(/\s+/)[0] ?? "";
2393	    }
2394	    exe = exe.trim();
2395	    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
2396	    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
2397	    const key = `${m[1]}|${exe}`;
2398	    if (seen.has(key) || out.length >= 12) continue;
2399	    seen.add(key);
2400	    out.push({ directive: m[1], path: exe });
2401	  }
2402	  return out;
2403	}
