2559	/**
2560	 * AFTER enabling the migrated units, prove each one is actually up.
2561	 *
2562	 * `systemctl enable --now` returning 0 means "systemd accepted the job", not
2563	 * "the program runs" — and `is-active` sampled immediately after can read
2564	 * `activating` for a unit that is about to die, or even `active` in the window
2565	 * between a restart and the next crash. So we settle, then sample the restart
2566	 * counter TWICE: a unit whose NRestarts is climbing is crash-looping no matter
2567	 * what its state says at any instant. A service that has restarted 78 times must
2568	 * never be silent.
2569	 */
2570	async function unitHealthGate(opts: {
2571	  conn: Client;
2572	  units: string[];
2573	  say: (line: string) => Promise<void>;
2574	}): Promise<{ healthy: string[]; blockers: PendingItem[] }> {
2575	  const { conn, units, say } = opts;
2576	  const healthy: string[] = [];
2577	  const blockers: PendingItem[] = [];
2578	  const list = units.filter((u) => SVCNAME_RE.test(u)).slice(0, 30);
2579	  if (!list.length) return { healthy, blockers };
2580	
2581	  await say(`  Waiting for ${list.length} migrated service(s) to settle before judging them.`);
2582	  await delay(12_000);
2583	  const first = new Map<string, UnitState>();
2584	  for (const u of list) first.set(u, await unitState(conn, u));
2585	  // A crash-loop needs a second look: RestartSec is typically 100ms–5s, so a
2586	  // 15-second window catches any unit that is cycling.
2587	  await delay(15_000);
2588	
2589	  for (const u of list) {
2590	    const a = first.get(u) ?? { active: "unknown", sub: "", restarts: 0 };
2591	    const b = await unitState(conn, u);
2592	    const climbing = b.restarts > a.restarts;
2593	    const ok = b.active === "active" && !climbing;
2594	    if (ok) {
2595	      healthy.push(u);
2596	      continue;
2597	    }
2598	
2599	    const journal = await unitJournal(conn, u);
2600	    const tail = journal.split("\n").filter((l) => l.trim()).slice(-4).join(" | ").slice(0, 400);
2601	    const state = climbing
2602	      ? `it is crash-looping — systemd has restarted it ${b.restarts} time(s) and the counter went up again while we watched`
2603	      : b.active === "failed"
2604	        ? `it is in the failed state (${b.sub || "failed"})`
2605	        : `it never became active (systemd reports ${b.active}${b.sub ? `/${b.sub}` : ""})`;
2606	
2607	    if (NEXT_NO_BUILD_RE.test(journal)) {
2608	      blockers.push({
2609	        domain: `${u}.service`,
2610	        why:
2611	          `${state}. The application was copied across but was never BUILT here — Next.js reports ` +
2612	          `"Could not find a production build in the '.next' directory", so it exits immediately every time`,
2613	        fix: `run the production build in the app's directory, then start it: npm ci --omit=dev && npx next build && systemctl restart ${u}`,
2614	      });
2615	      await say(`  ${u}: not running — the app has no production build on this server (\`next build\` has never been run here).`);
2616	      continue;
2617	    }
2618	
2619	    blockers.push({
2620	      domain: `${u}.service`,
2621	      why: `${state}${tail ? `. Its last log lines were: ${tail}` : ""}`,
2622	      fix: `systemctl status ${u} --no-pager -l; journalctl -u ${u} -n 50 --no-pager`,
2623	    });
2624	    await say(`  ${u}: NOT running — ${state}.`);
2625	  }
2626	  return { healthy, blockers };
2627	}
