467	// ---- Heartbeats for the long steps ----------------------------------------
468	/**
469	 * A single remote command can legitimately run for MINUTES — `apt-get install`,
470	 * `docker save | ssh | docker load`, `certbot certonly`. During that time the
471	 * engine emits nothing, so the customer's progress bar freezes and the run looks
472	 * hung.
473	 *
474	 * Seen live on 2026-07-25: the run sat silent on 89% "Securing your site…" for a
475	 * full TEN MINUTES while a certbot install blocked on needrestart. The customer
476	 * had no way to tell a wedged migration from a slow one.
477	 *
478	 * So the long steps run inside this wrapper, which emits ONE cheap line every
479	 * `everyMs` naming what is still running and for how long. It is deliberately
480	 * dumb: no extra SSH traffic, no state on the target, and a failing `say` can
481	 * never affect the work it is narrating.
482	 */
483	const HEARTBEAT_MS = 45_000;
484	
485	async function withHeartbeat<T>(
486	  what: string,
487	  say: (line: string) => Promise<void>,
488	  run: () => Promise<T>,
489	  everyMs: number = HEARTBEAT_MS
490	): Promise<T> {
491	  const started = Date.now();
492	  let saying = false;
493	  const timer = setInterval(() => {
494	    // Never let two heartbeats overlap, and never let a reporting failure
495	    // surface as an unhandled rejection — this is narration, not work.
496	    if (saying) return;
497	    saying = true;
498	    const secs = Math.round((Date.now() - started) / 1000);
499	    const elapsed = secs >= 120 ? `${Math.round(secs / 60)} min` : `${secs}s`;
500	    Promise.resolve(say(`  Still working: ${what} (${elapsed} so far) — this step can take a while.`))
501	      .catch(() => {})
502	      .finally(() => {
503	        saying = false;
504	      });
505	  }, Math.max(15_000, everyMs));
506	  // `unref` keeps a stray interval from holding the worker process open.
507	  (timer as unknown as { unref?: () => void }).unref?.();
508	  try {
509	    return await run();
510	  } finally {
511	    clearInterval(timer);
512	  }
513	}
