516	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
517	  return new Promise((resolve, reject) => {
518	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
519	    ws.on("close", () => resolve());
520	    ws.on("error", (e: Error) => reject(e));
521	    ws.end(Buffer.from(content, "utf8"));
522	  });
523	}
