216	// ---- Strict allowlist validators (mirror worker/migrate-real.ts) ----------
217	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
218	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
219	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
