224	// transfer engine can actually migrate, so nothing selected here fails later.
225	const DBNAME_RE = /^[A-Za-z0-9_]{1,64}$/;
226	// Informational identifiers that come BACK from the source. These are never used
227	// in a shell or selected for transfer — only rendered as text — but we still keep
228	// them shell-inert and bounded so nothing weird flows through.
229	const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
230	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
231	// A Docker image reference. Shell-inert charset (no quotes/space/metachars), so a
232	// validated ref is safe to interpolate. MUST stay in sync with IMAGEREF_RE in
233	// worker/migrate-real.ts — only surface refs the real engine can actually move.
234	const IMAGEREF_RE = /^[A-Za-z0-9][A-Za-z0-9._:@/-]{0,254}$/;
