236	// must contain a dot, no wildcards. MUST stay in sync with DOMAIN_RE in
237	// worker/migrate-real.ts.
238	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
