240	/** Strip control chars, trim and bound the length of any free text from the source. */
241	function cleanText(s: string, max: number): string {
242	  // eslint-disable-next-line no-control-regex
243	  return (s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
