709	export async function detectSource(input: DetectInput): Promise<ScanResult> {
710	  assert(validHost(input.host), "source host is not a valid hostname or IP address");
711	  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
712	  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
713	  assert(input.password && input.password.length > 0, "source SSH password is required");
714	
715	  const notes: string[] = [];
716	  const webRoots: DetectedWebRoot[] = [];
717	  const homes: DetectedHome[] = [];
718	  const databases: DetectedDatabase[] = [];
719	  const engines: DetectedEngine[] = [];
720	  const rawAppDirs: DetectedAppDir[] = [];
721	  const containers: DetectedContainer[] = [];
722	  const ports: DetectedPort[] = [];
723	  const services: DetectedService[] = [];
724	  const seenPort = new Set<string>();
725	  const dockerImages: DetectedImage[] = [];
726	  const vhostDomains: string[] = [];
727	  const webServerConfigs: ("nginx" | "apache2" | "httpd")[] = [];
728	  const tlsCertDomains: string[] = [];
729	  let dockerVolumeBytes = 0;
730	  let cronCount = 0;
731	  let dbSizeBytes = 0;
732	  let sourceArch: string | null = null;
733	  const osrel: { id?: string; versionId?: string; pretty?: string } = {};
734	  // Raw `--version` banners per engine, parsed after the scan loop.
735	  const dbVerRaw: Record<"mysql" | "postgres", string> = { mysql: "", postgres: "" };
736	
737	  const conn = await connectSource(input);
738	  try {
739	    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
740	    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
741	    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
742	      mysql: { present: false, listening: false },
743	      postgres: { present: false, listening: false },
744	    };
745	
746	    for (const raw of scan.stdout.split("\n")) {
747	      const line = raw.replace(/\r$/, "");
748	      if (!line) continue;
749	      const parts = line.split("\t");
750	      if (parts[0] === "WEB" && parts.length >= 4) {
751	        const appType = parts[1] as WebAppType;
752	        const sizeLabel = parts[2] || "?";
753	        const path = normalizeRemotePath(parts[3]);
754	        if (!validPath(path)) continue;
755	        if (webRoots.some((w) => w.path === path)) continue;
756	        webRoots.push({
757	          path,
758	          sizeLabel,
759	          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
760	            ? appType
761	            : "unknown",
762	        });
763	      } else if (parts[0] === "HOME" && parts.length >= 3) {
764	        const sizeLabel = parts[1] || "?";
765	        const path = normalizeRemotePath(parts[2]);
766	        if (!validPath(path)) continue;
767	        if (homes.some((h) => h.path === path)) continue;
768	        homes.push({ path, sizeLabel });
769	      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
770	        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
771	        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
772	      } else if (parts[0] === "APPDIR" && parts.length >= 5) {
773	        const sizeLabel = parts[3] || "?";
774	        const path = normalizeRemotePath(parts[4]);
775	        if (!validPath(path)) continue; // candidate for TRANSFER — must pass the strict allowlist
776	        rawAppDirs.push({
777	          path,
778	          sizeLabel,
779	          runtime: mapRuntime(parts[1]),
780	          signature: mapSignature(parts[2]),
781	        });
782	      } else if (parts[0] === "DOCKER") {
783	        // Line body is "name|image|ports|mounts" (never contains a tab, so parts[1] holds it whole).
784	        if (containers.length >= MAX_CONTAINERS) continue;
785	        const seg = (parts.slice(1).join("\t")).split("|");
786	        const name = cleanText(seg[0] ?? "", 128);
787	        if (!CONTNAME_RE.test(name)) continue; // shell-inert display id
788	        if (containers.some((c) => c.name === name)) continue;
789	        const mounts = (seg[3] ?? "")
